    function getUserVaultStorageKey() {
      const email = (appState.currentUser && appState.currentUser.email) ? appState.currentUser.email.toLowerCase() : 'local_device_guest';
      const safeSlug = email.replace(/[^a-z0-9]/g, '_');
      return 'bajrang_private_vault_v8_' + safeSlug;
    }

    function loadUserPrivateByoSettings() {
      const vKey = getUserVaultStorageKey();
      const lbl = document.getElementById('vault-namespace-label');
      if (lbl) lbl.textContent = vKey;
      try {
        const raw = localStorage.getItem(vKey);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && typeof parsed === 'object') return parsed;
        }
      } catch (e) {}
      return {
        provider: 'gemini_argon',
        apiKey: '',
        endpoint: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
        model: 'gemini-2.5-flash'
      };
    }

    function saveUserPrivateByoSettings(settingsObj) {
      const vKey = getUserVaultStorageKey();
      try {
        localStorage.setItem(vKey, JSON.stringify(settingsObj));
      } catch (e) {}
    }

    let currentPrivateByo = loadUserPrivateByoSettings();

    function loadAppState() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && Array.isArray(parsed.sessions)) {
            const merged = Object.assign({}, DEFAULT_STATE, parsed);
            merged.ownerUnlocked = false;
            delete merged.byoSettings;
            return merged;
          }
        }
      } catch (e) {}
      return JSON.parse(JSON.stringify(DEFAULT_STATE));
    }

    function saveAppState() {
      try {
        const copy = Object.assign({}, appState);
        delete copy.byoSettings;
        localStorage.setItem(STORAGE_KEY, JSON.stringify(copy));
      } catch (e) {}
    }

    function appendSiemLog(severity, eventType, actor, details) {
      const entry = {
        ts: new Date().toISOString().replace('T', ' ').slice(0, 19),
        severity: severity,
        event: eventType,
        actor: actor || (appState.currentUser ? appState.currentUser.email : 'anonymous'),
        details: details
      };
      if (!Array.isArray(appState.siemLogs)) appState.siemLogs = [];
      appState.siemLogs.unshift(entry);
      if (appState.siemLogs.length > 200) appState.siemLogs.pop();
      saveAppState();
      renderSiemLogsTable();
      syncToSupabaseIfConfigured('siem_logs', entry);
    }

    async function syncToSupabaseIfConfigured(tableName, recordObj) {
      const cfg = appState.cloudConfig || {};
      if (!cfg.supabaseUrl || !cfg.supabaseAnonKey) return;
      try {
        const url = cfg.supabaseUrl.replace(/\/+$/, '') + '/rest/v1/' + tableName;
        await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'apikey': cfg.supabaseAnonKey,
            'Authorization': 'Bearer ' + cfg.supabaseAnonKey,
            'Prefer': 'return=minimal'
          },
          body: JSON.stringify(recordObj)
        });
      } catch (e) {}
    }

    function showToast(message, tone) {
      const container = document.getElementById('toast-container');
      if (!container) return;
      const toast = document.createElement('div');
      const isErr = tone === 'error';
      toast.className = 'pointer-events-auto px-4 py-2.5 rounded-xl border text-xs font-bold shadow-xl transition-all ' +
        (isErr ? 'border-red-500 bg-red-950 text-red-200' : 'border-emerald-500 bg-slate-900 text-emerald-300');
      toast.textContent = message;
      container.appendChild(toast);
      setTimeout(function () { toast.remove(); }, 3200);
    }

    async function pasteApiKeyFromClipboard() {
      if (navigator.clipboard && navigator.clipboard.readText) {
        try {
          const txt = (await navigator.clipboard.readText() || '').trim();
          if (txt) {
            const qInp = document.getElementById('quick-api-key-input');
            const bInp = document.getElementById('byo-key-input');
            if (qInp) qInp.value = txt;
            if (bInp) bInp.value = txt;
            autoDetectKeyProvider(txt, true);
            showToast('Pasted key from clipboard! Click Activate to connect.');
            return;
          }
        } catch (e) {}
      }
      showToast('Tap the key input box and press Paste (Ctrl+V / Long-press Paste).');
    }

    function copyCommand(elementId) {
      const el = document.getElementById(elementId);
      if (!el) return;
      const text = (el.textContent || el.innerText || '').trim();
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          showToast('Copied: ' + text.slice(0, 32));
        }).catch(function () { fallbackCopy(text); });
      } else {
        fallbackCopy(text);
      }
    }

    function fallbackCopy(text) {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand('copy');
        showToast('Copied to clipboard!');
      } catch (e) {
        showToast('Select text and press Ctrl+C.');
      }
      ta.remove();
    }

    function toggleTheme() {
      const htmlEl = document.documentElement;
      const cur = htmlEl.classList.contains('dark') ? 'dark' : 'light';
      const nxt = cur === 'dark' ? 'light' : 'dark';
      applyTheme(nxt);
      appState.theme = nxt;
      saveAppState();
      showToast('Switched to ' + (nxt === 'light' ? 'Bright Mode' : 'Dark Mode'));
    }

    function applyTheme(themeName) {
      const htmlEl = document.documentElement;
      const icon = document.getElementById('theme-icon');
      const text = document.getElementById('theme-text');
      if (themeName === 'light') {
        htmlEl.classList.remove('dark');
        htmlEl.classList.add('light');
        if (icon) icon.textContent = '🌙';
        if (text) text.textContent = 'Dark';
      } else {
        htmlEl.classList.remove('light');
        htmlEl.classList.add('dark');
        if (icon) icon.textContent = '☀️';
        if (text) text.textContent = 'Bright';
      }
    }


    function toggleSideMenu() {
      const drawer = document.getElementById('side-menu-drawer');
      const backdrop = document.getElementById('side-menu-backdrop');
      if (!drawer || !backdrop) return;
      const isClosed = drawer.classList.contains('-translate-x-full');
      if (isClosed) {
        drawer.classList.remove('-translate-x-full');
        backdrop.classList.remove('hidden');
      } else {
        drawer.classList.add('-translate-x-full');
        backdrop.classList.add('hidden');
      }
    }

    function closeSideMenu() {
      const drawer = document.getElementById('side-menu-drawer');
      const backdrop = document.getElementById('side-menu-backdrop');
      if (drawer) drawer.classList.add('-translate-x-full');
      if (backdrop) backdrop.classList.add('hidden');
    }

    function jumpToHomeFounderStory() {
      switchTab('simulator');
      closeSideMenu();
      const el = document.getElementById('home-founder-story-section');
      if (el && el.scrollIntoView) {
        el.scrollIntoView({ behavior: 'smooth' });
      }
    }

    function switchTab(tabName) {
      if (tabName === 'owner-admin' && !appState.ownerUnlocked) {
        openOwnerLoginModal();
        return;
      }
      appState.activeTab = tabName;
      const tabs = ['simulator', 'downloads', 'byokey', 'pricing', 'founder', 'install', 'owner-admin'];
      tabs.forEach(function (t) {
        const sec = document.getElementById('tab-' + t);
        const btn = document.getElementById('nav-btn-' + t);
        if (sec) sec.classList.toggle('hidden', t !== tabName);
        if (btn) {
          btn.className = (t === tabName)
            ? 'w-full text-left px-3.5 py-2.5 rounded-xl bg-indigo-600 text-white font-bold text-xs flex items-center justify-between transition'
            : 'w-full text-left px-3.5 py-2.5 rounded-xl text-sec hover:bg-indigo-500/10 font-bold text-xs flex items-center justify-between transition';
        }
      });
      saveAppState();
    }

    function autoDetectKeyProvider(rawKey, isQuickBar) {
      let clean = (rawKey || '').trim().replace(/^['"]+|['"]+$/g, '');
      if (clean.toLowerCase().indexOf('bearer ') === 0) {
        clean = clean.slice(7).trim();
      }
      let provider = 'gemini_argon';
      let endpoint = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent';
      let model = 'gemini-2.5-flash';
      let label = 'Paste your private API key';

      if (clean.indexOf('AIza') === 0) {
        provider = 'gemini_argon';
        endpoint = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent';
        model = 'gemini-2.5-flash';
        label = 'Detected: Google Gemini Key (AIza* • Private Vault)';
      } else if (clean.indexOf('gsk_') === 0) {
        provider = 'groq';
        endpoint = 'https://api.groq.com/openai/v1/chat/completions';
        model = 'llama-3.3-70b-versatile';
        label = 'Detected: Groq Cloud Key (gsk_* • Private Vault)';
      } else if (clean.indexOf('sk-or-') === 0) {
        provider = 'openrouter';
        endpoint = 'https://openrouter.ai/api/v1/chat/completions';
        model = 'meta-llama/llama-3.2-3b-instruct:free';
        label = 'Detected: OpenRouter Key (sk-or-* • Private Vault)';
      } else if (clean.indexOf('sk-') === 0) {
        provider = 'openai';
        endpoint = 'https://api.openai.com/v1/chat/completions';
        model = 'gpt-4o-mini';
        label = 'Detected: OpenAI Key (sk-* • Private Vault)';
      }

      const badge = document.getElementById('quick-key-detected-badge');
      if (badge && clean.length > 4) badge.textContent = label;

      const provSel = document.getElementById('byo-provider-select');
      const endInp = document.getElementById('byo-endpoint-input');
      const modInp = document.getElementById('byo-model-input');
      const byoInp = document.getElementById('byo-key-input');
      const quickInp = document.getElementById('quick-api-key-input');

      if (clean.length > 4) {
        if (provSel) provSel.value = provider;
        if (endInp) endInp.value = endpoint;
        if (modInp) modInp.value = model;
        if (isQuickBar && byoInp) byoInp.value = clean;
        if (!isQuickBar && quickInp) quickInp.value = clean;
      }
      return { provider: provider, apiKey: clean, endpoint: endpoint, model: model, label: label };
    }

    async function callLiveCloudAi(promptText, sysPrompt) {
      const cfg = currentPrivateByo || {};
      const key = (cfg.apiKey || '').trim();
      if (!key || key.length < 6) {
        return { ok: false, text: '', error: 'No private API key configured yet.' };
      }

      if (cfg.provider === 'gemini_argon' || key.indexOf('AIza') === 0) {
        const modelsToTry = [cfg.model || 'gemini-2.5-flash', 'gemini-2.5-flash', 'gemini-2.0-flash'];
        for (let i = 0; i < modelsToTry.length; i++) {
          const m = modelsToTry[i];
          const url = 'https://generativelanguage.googleapis.com/v1beta/models/' + m + ':generateContent?key=' + encodeURIComponent(key);
          try {
            const resp = await fetch(url, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                systemInstruction: { parts: [{ text: sysPrompt }] },
                contents: [{ role: 'user', parts: [{ text: promptText }] }],
                generationConfig: { temperature: 0.25 }
              })
            });
            if (resp.ok) {
              const data = await resp.json();
              const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
              const out = parts.map(function (p) { return p.text || ''; }).join('').trim();
              if (out) return { ok: true, text: out, model: m };
            }
          } catch (e) {}
        }
      }

      try {
        const resp = await fetch(cfg.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + key
          },
          body: JSON.stringify({
            model: cfg.model,
            messages: [
              { role: 'system', content: sysPrompt },
              { role: 'user', content: promptText }
            ],
            temperature: 0.25
          })
        });
        if (resp.ok) {
          const data = await resp.json();
          const out = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
          if (out) return { ok: true, text: out, model: cfg.model };
        } else {
          const errTxt = await resp.text();
          return { ok: false, text: '', error: 'HTTP ' + resp.status + ': ' + errTxt.slice(0, 120) };
        }
      } catch (err) {
        return { ok: false, text: '', error: String(err) };
      }
      return { ok: false, text: '', error: 'API request failed. Verify your API key.' };
    }

