    function toggleSingleVoiceCapture() {
      if (isListeningNow) {
        stopRealVoiceRecognition();
      } else {
        startRealVoiceRecognition();
      }
    }

    function stopRealVoiceRecognition() {
      isListeningNow = false;
      if (activeRecognition) {
        try { activeRecognition.stop(); } catch (e) {}
        activeRecognition = null;
      }
      if (mediaRecorder && mediaRecorder.state !== 'inactive') {
        try { mediaRecorder.stop(); } catch (e) {}
      }
      stopLiveMicVisualizer();
      setVoiceUiState(false, 'Ready to Speak', null);
      updateEngineStatusUI();
    }

    async function startRealVoiceRecognition() {
      stopSpeakingNow();
      setAgentStatus('listening', 'Listening via Microphone...');
      setVoiceUiState(true, 'Listening Live...', '🎙️ Listening... speak your question or command now.');
      const stream = await startLiveMicVisualizer();

      const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
      if (SR) {
        try {
          const rec = new SR();
          activeRecognition = rec;
          rec.lang = (appState.voicePrefs && appState.voicePrefs.lang) || 'en-IN';
          rec.continuous = false;
          rec.interimResults = true;
          rec.maxAlternatives = 1;

          let finalTranscript = '';
          letinterimSeen = '';

          rec.onresult = function (event) {
            let interim = '';
            for (let i = event.resultIndex; i < event.results.length; i++) {
              const t = event.results[i][0].transcript;
              if (event.results[i].isFinal) {
                finalTranscript += t + ' ';
              } else {
                interim += t;
              }
            }
            const displayStr = (finalTranscript + interim).trim();
            if (displayStr) {
              letinterimSeen = displayStr;
              setVoiceUiState(true, 'Transcribing Live...', '🗣️ "' + displayStr + '"');
              const inp = document.getElementById('hud-prompt-input');
              if (inp) inp.value = displayStr;
            }
          };

          rec.onend = function () {
            stopLiveMicVisualizer();
            const spoken = (finalTranscript || letinterimSeen || '').trim();
            const inp = document.getElementById('hud-prompt-input');
            if (inp) inp.value = '';
            if (spoken) {
              setVoiceUiState(false, 'Processed Speech', '✅ You said: "' + spoken + '"');
              runAssistantPrompt(spoken, true);
            } else {
              setVoiceUiState(false, 'No Speech Detected', 'No speech heard. Tap Speak Now and talk into your microphone.');
              updateEngineStatusUI();
              if (continuousCallActive) {
                setTimeout(function () { if (continuousCallActive && !isListeningNow) startRealVoiceRecognition(); }, 600);
              }
            }
          };

          rec.onerror = function (ev) {
            if (ev && ev.error === 'not-allowed') {
              stopLiveMicVisualizer();
              setVoiceUiState(false, 'Mic Permission Blocked', '⚠️ Please allow Microphone access in your browser address bar.');
              showToast('Microphone permission denied by browser. Allow mic access in address bar.', 'error');
              return;
            }
            if (stream && currentPrivateByo && currentPrivateByo.apiKey) {
              startMultimodalAudioRecorderFallback(stream);
            } else {
              stopLiveMicVisualizer();
              setVoiceUiState(false, 'Voice Ready', 'Tap Speak Now or type below.');
            }
          };

          rec.start();
          return;
        } catch (e) {}
      }

      if (stream) {
        startMultimodalAudioRecorderFallback(stream);
      } else {
        setVoiceUiState(false, 'Mic Unavailable', '⚠️ Allow microphone permission in your browser to use live voice.');
        showToast('Please allow microphone access in your browser.', 'error');
      }
    }

    function startMultimodalAudioRecorderFallback(stream) {
      if (typeof MediaRecorder === 'undefined') {
        stopLiveMicVisualizer();
        setVoiceUiState(false, 'Unsupported Browser Audio', 'Use Chrome, Edge, Safari, or Brave with a Gemini API key.');
        return;
      }
      recordedAudioChunks = [];
      try {
        mediaRecorder = new MediaRecorder(stream);
      } catch (e) {
        stopLiveMicVisualizer();
        return;
      }
      setVoiceUiState(true, 'Recording Audio for AI STT (4s)...', '🎙️ Recording audio... speak now (tap Stop & Send when done).');
      mediaRecorder.ondataavailable = function (e) {
        if (e.data && e.data.size > 0) recordedAudioChunks.push(e.data);
      };
      mediaRecorder.onstop = async function () {
        stopLiveMicVisualizer();
        const blob = new Blob(recordedAudioChunks, { type: mediaRecorder.mimeType || 'audio/webm' });
        setVoiceUiState(false, 'Transcribing via Private AI Key...', '⏳ Sending recorded audio to your private API key...');
        const transcript = await transcribeBlobWithCloudKey(blob);
        if (transcript) {
          setVoiceUiState(false, 'Transcribed!', '✅ You said: "' + transcript + '"');
          runAssistantPrompt(transcript, true);
        } else {
          setVoiceUiState(false, 'Paste Gemini Key for Audio STT', 'Paste a Gemini (AIza*) key in the top bar for universal multimodal voice transcription.');
        }
      };
      mediaRecorder.start();
      setTimeout(function () {
        if (mediaRecorder && mediaRecorder.state === 'recording') {
          try { mediaRecorder.stop(); } catch (e) {}
        }
      }, 4500);
    }

    async function transcribeBlobWithCloudKey(audioBlob) {
      const key = (currentPrivateByo && currentPrivateByo.apiKey) ? currentPrivateByo.apiKey.trim() : '';
      if (!key || key.indexOf('AIza') !== 0) return '';
      const base64Audio = await new Promise(function (resolve) {
        const reader = new FileReader();
        reader.onloadend = function () {
          const res = reader.result || '';
          resolve(res.split(',')[1] || '');
        };
        reader.readAsDataURL(audioBlob);
      });
      if (!base64Audio) return '';
      const mime = (audioBlob.type || 'audio/webm').split(';')[0];
      const url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + encodeURIComponent(key);
      try {
        const resp = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{
              role: 'user',
              parts: [
                { text: 'Transcribe the spoken words in this audio accurately. Return ONLY the exact spoken words, nothing else.' },
                { inlineData: { mimeType: mime, data: base64Audio } }
              ]
            }],
            generationConfig: { temperature: 0.0 }
          })
        });
        if (resp.ok) {
          const data = await resp.json();
          const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
          return parts.map(function (p) { return p.text || ''; }).join('').trim();
        }
      } catch (e) {}
      return '';
    }

    function speakTextIfEnabled(text, onFinishedCallback) {
      const ttsBox = document.getElementById('tts-checkbox');
      if (!ttsBox || !ttsBox.checked || !('speechSynthesis' in window)) {
        if (onFinishedCallback) onFinishedCallback();
        return;
      }
      try {
        window.speechSynthesis.cancel();
        const cleanSpeech = text.replace(/[*_`#]/g, '');
        const utter = new SpeechSynthesisUtterance(cleanSpeech);
        const prefs = appState.voicePrefs || { lang: 'en-IN', speed: 1.15, voiceName: 'default' };
        utter.lang = prefs.lang || 'en-IN';
        utter.rate = prefs.speed || 1.15;
        if (prefs.voiceName && prefs.voiceName !== 'default') {
          const voices = window.speechSynthesis.getVoices() || [];
          const matched = voices.find(function (v) { return v.name === prefs.voiceName; });
          if (matched) utter.voice = matched;
        }
        utter.onend = function () {
          if (onFinishedCallback) onFinishedCallback();
        };
        utter.onerror = function () {
          if (onFinishedCallback) onFinishedCallback();
        };
        window.speechSynthesis.speak(utter);
      } catch (e) {
        if (onFinishedCallback) onFinishedCallback();
      }
    }

