    function triggerGoogleOAuthLogin() {
      const clientId = (appState.cloudConfig && appState.cloudConfig.googleClientId) ? appState.cloudConfig.googleClientId.trim() : '';
      if (window.google && window.google.accounts && window.google.accounts.oauth2 && clientId) {
        const tokenClient = window.google.accounts.oauth2.initTokenClient({
          client_id: clientId,
          scope: 'openid email profile',
          callback: async function (tokenResponse) {
            if (tokenResponse && tokenResponse.access_token) {
              try {
                const resp = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
                  headers: { 'Authorization': 'Bearer ' + tokenResponse.access_token }
                });
                const profile = await resp.json();
                completeUserSignIn(profile.name || 'Google User', profile.email, profile.picture, 'google_oauth2');
              } catch (e) {
                showToast('Failed to fetch Google userinfo profile.', 'error');
              }
            }
          }
        });
        tokenClient.requestAccessToken();
        return;
      }
      showToast('Enter your Google email & name below (or add your Google Client ID in Owner Console for 1-click Google popup).');
      const emailInp = document.getElementById('custom-google-email');
      if (emailInp) emailInp.focus();
    }

    function registerOrLoginAccount() {
      const nameInp = document.getElementById('custom-google-name');
      const emailInp = document.getElementById('custom-google-email');
      const passInp = document.getElementById('custom-account-password');
      const email = emailInp ? emailInp.value.trim().toLowerCase() : '';
      const pass = passInp ? passInp.value : '';
      if (!email || email.indexOf('@') === -1) {
        showToast('Please enter a valid email address.', 'error');
        return;
      }
      if (!pass || pass.length < 4) {
        showToast('Please enter a password (at least 4 characters).', 'error');
        return;
      }
      const name = (nameInp && nameInp.value.trim()) ? nameInp.value.trim() : email.split('@')[0];
      let hash = 2166136261;
      for (let i = 0; i < pass.length; i++) {
        hash ^= pass.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
      }
      const passHash = (hash >>> 0).toString(16);

      if (!Array.isArray(appState.accounts)) appState.accounts = [];
      const existing = appState.accounts.find(function (a) { return a.email === email; });
      if (existing) {
        if (existing.passHash !== passHash) {
          appendSiemLog('WARN', 'USER_LOGIN_FAILED', email, 'Invalid password for existing user account.');
          showToast('Incorrect password for ' + email, 'error');
          return;
        }
        completeUserSignIn(existing.name, email, null, 'account_login');
      } else {
        const newAcc = { name: name, email: email, passHash: passHash, created_at: new Date().toISOString() };
        appState.accounts.push(newAcc);
        syncToSupabaseIfConfigured('users', { name: name, email: email, created_at: newAcc.created_at });
        completeUserSignIn(name, email, null, 'account_created');
      }
    }

    function completeUserSignIn(name, email, pictureUrl, method) {
      const initial = (name || email || 'U').trim().charAt(0).toUpperCase();
      appState.currentUser = {
        name: name,
        email: email.toLowerCase(),
        avatar: pictureUrl || ("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28'><circle cx='14' cy='14' r='14' fill='%234f46e5'/><text x='14' y='18' font-size='12' fill='%23fff' text-anchor='middle' font-family='sans-serif'>" + initial + "</text></svg>")
      };
      currentPrivateByo = loadUserPrivateByoSettings();
      const qInp = document.getElementById('quick-api-key-input');
      const bInp = document.getElementById('byo-key-input');
      if (qInp) qInp.value = currentPrivateByo.apiKey || '';
      if (bInp) bInp.value = currentPrivateByo.apiKey || '';
      appendSiemLog('INFO', method.toUpperCase(), email, 'User authenticated (' + name + ') & switched to isolated private key vault.');
      saveAppState();
      renderCurrentUserProfile();
      updateEngineStatusUI();
      closeAccountModal();
      showToast('Signed in as ' + email + ' (Private Vault Loaded)');
      const checkoutEmail = document.getElementById('checkout-email');
      if (checkoutEmail) checkoutEmail.value = email;
    }

