    function authenticateOwnerVault(event) {
      event.preventDefault();
      const emailInp = document.getElementById('owner-email-input');
      const passInp = document.getElementById('owner-passkey-input');
      const errBox = document.getElementById('owner-login-error');
      const email = (emailInp ? emailInp.value : '').trim().toLowerCase();
      const pass = (passInp ? passInp.value : '').trim();

      if (appState.failedOwnerAttempts >= 5) {
        if (errBox) {
          errBox.classList.remove('hidden');
          errBox.textContent = '🛑 Brute-force lockout active. Too many failed Owner login attempts.';
        }
        appendSiemLog('CRITICAL', 'OWNER_LOCKOUT_TRIGGERED', email || 'unknown', 'Blocked after 5 failed Owner Vault attempts.');
        return;
      }

      if (email === OWNER_EMAIL_HASH && pass === OWNER_DEFAULT_PASSKEY) {
        appState.ownerUnlocked = true;
        appState.failedOwnerAttempts = 0;
        if (errBox) errBox.classList.add('hidden');
        if (passInp) passInp.value = '';
        appendSiemLog('INFO', 'OWNER_VAULT_UNLOCKED', email, 'Owner authenticated into Admin & SIEM Console.');
        closeOwnerLoginModal();
        renderUpiApprovalQueue();
        renderSiemLogsTable();
        switchTab('owner-admin');
        showToast('Welcome Kaushik! Owner Admin & SIEM Vault unlocked.');
      } else {
        appState.failedOwnerAttempts = (appState.failedOwnerAttempts || 0) + 1;
        appendSiemLog('CRITICAL', 'UNAUTHORIZED_OWNER_LOGIN_ATTEMPT', email || 'unknown', 'Failed Owner Passkey attempt #' + appState.failedOwnerAttempts);
        if (errBox) {
          errBox.classList.remove('hidden');
          errBox.textContent = '✕ Access Denied: Invalid Owner Email or Passkey (Attempt ' + appState.failedOwnerAttempts + '/5).';
        }
      }
    }

