    function renderUpiApprovalQueue() {
      const box = document.getElementById('upi-approval-queue-list');
      const badge = document.getElementById('pending-upi-count-badge');
      if (!box) return;
      const list = appState.pendingUpiPayments || [];
      const pendingCnt = list.filter(function (x) { return x.status === 'PENDING_OWNER_APPROVAL'; }).length;
      if (badge) badge.textContent = pendingCnt + ' Pending';
      if (list.length === 0) {
        box.innerHTML = '<div class="p-3 rounded-xl theme-subcard text-mut text-center">No UPI payment submissions in queue yet.</div>';
        return;
      }
      box.innerHTML = '';
      list.forEach(function (item) {
        const div = document.createElement('div');
        div.className = 'p-3 rounded-xl theme-subcard flex flex-wrap items-center justify-between gap-2';
        let rightHtml = '';
        if (item.status === 'PENDING_OWNER_APPROVAL') {
          rightHtml = '<div class="flex gap-1.5">' +
            '<button type="button" onclick="ownerApproveUpiPayment(&quot;' + item.id + '&quot;)" class="px-3 py-1 rounded-lg bg-emerald-600 text-white font-bold">✅ Confirm &amp; Unlock</button>' +
            '<button type="button" onclick="ownerRejectUpiPayment(&quot;' + item.id + '&quot;)" class="px-2.5 py-1 rounded-lg bg-red-600/30 text-red-300 font-bold">✕ Reject</button>' +
            '</div>';
        } else if (item.status === 'APPROVED') {
          rightHtml = '<span class="font-mono text-[11px] text-emerald-400 font-bold">✅ APPROVED (' + (item.issued_key || '') + ')</span>';
        } else {
          rightHtml = '<span class="font-mono text-[11px] text-red-400 font-bold">✕ REJECTED</span>';
        }
        div.innerHTML = '<div><div class="font-bold">' + item.email + ' • <span class="text-amber-400">' + item.plan + '</span></div>' +
          '<div class="font-mono text-[11px] text-mut">UTR: <strong class="text-sec">' + item.utr + '</strong> • To: 9392659952@fam • ' + item.ts + '</div></div>' + rightHtml;
        box.appendChild(div);
      });
    }

    function verifyLicenseOrApprovalStatus() {
      const inp = document.getElementById('verify-key-input');
      const out = document.getElementById('verify-key-result');
      if (!inp || !out) return;
      const val = inp.value.trim();
      const lower = val.toLowerCase();
      if (appState.approvedLicenses && appState.approvedLicenses[lower]) {
        const k = appState.approvedLicenses[lower];
        out.className = 'text-xs font-mono text-emerald-400 font-bold';
        out.textContent = '✅ OWNER APPROVED! Your Pro License Key: ' + k;
        return;
      }
      const pending = (appState.pendingUpiPayments || []).find(function (p) { return p.email === lower; });
      if (pending) {
        out.className = 'text-xs font-mono text-amber-400 font-bold';
        out.textContent = '⏳ Status for ' + lower + ': ' + pending.status + ' (UTR ' + pending.utr + ')';
        return;
      }
      const parts = val.toUpperCase().split('-');
      if (parts.length === 5 && parts[0] === 'BAJRANG' && parts[1] === 'PRO') {
        out.className = 'text-xs font-mono text-emerald-400 font-bold';
        out.textContent = '✓ VALID PRO LICENSE • Subscriber: ' + parts[2] + ' • Expires: ' + parts[3];
      } else {
        out.className = 'text-xs font-mono text-red-400 font-bold';
        out.textContent = '✕ No approved Pro license found for "' + val + '". Pay ₹99 to 9392659952@fam and submit your UTR first.';
      }
    }

