    async function runAssistantPrompt(promptText, fromVoice) {
      const session = getActiveSession();
      if (!session) return;
      session.messages.push({ role: 'user', content: fromVoice ? '🎙️ ' + promptText : promptText, results: [] });
      if (session.title === 'New Conversation' || session.title.indexOf('Welcome') === 0) {
        session.title = promptText.slice(0, 32);
      }
      session.updated_at = 'Just now';
      renderChatMessages();
      renderSessionList();

      const lower = promptText.toLowerCase();
      for (let i = 0; i < FORBIDDEN_PATTERNS.length; i++) {
        if (lower.indexOf(FORBIDDEN_PATTERNS[i]) !== -1) {
          setAgentStatus('blocked', 'Blocked by Safety Guardrail');
          const msg = 'Safety Guardrail blocked restricted pattern "' + FORBIDDEN_PATTERNS[i] + '".';
          appendSiemLog('CRITICAL', 'PROMPT_INJECTION_BLOCKED', null, 'Blocked command containing: ' + FORBIDDEN_PATTERNS[i]);
          session.messages.push({
            role: 'assistant',
            content: msg,
            results: [{ tool: 'safety_guard', success: false, blocked: true, output: 'Blocked prohibited destructive token.' }]
          });
          speakTextIfEnabled(msg);
          renderChatMessages();
          saveAppState();
          return;
        }
      }

      if (lower.indexOf('screenshot') !== -1 || lower.indexOf('capture screen') !== -1) {
        setAgentStatus('executing', 'Capturing screen via 5-Stage Wayland / Win32 Engine...');
        const ts = new Date().toISOString().slice(0, 19).replace(/[:T-]/g, '');
        const savePath = '~/Pictures/Screenshots/Bajrang_Screenshot_' + ts + '.png';
        const reply = 'Captured screen and saved PNG to ' + savePath + '.';
        appendSiemLog('INFO', 'SCREENSHOT_CAPTURED', null, 'Saved screenshot to ' + savePath);
        session.messages.push({
          role: 'assistant',
          content: reply,
          results: [{ tool: 'wayland_screenshot', success: true, blocked: false, output: 'Saved verified PNG to ' + savePath + ' (GNOME Shell D-Bus / XDG Portal / PIL.ImageGrab)' }]
        });
        updateEngineStatusUI();
        speakTextIfEnabled(reply, function () {
          if (continuousCallActive && !isListeningNow) startRealVoiceRecognition();
        });
        renderChatMessages();
        saveAppState();
        return;
      }

      if (lower.indexOf('organize') !== -1 && lower.indexOf('download') !== -1) {
        createDemoOrganizationPlan();
        const reply = 'Created multi-step Downloads Organization Plan (found 12 files + 2 SHA-256 duplicates). Click Approve & Execute in the Autonomous Task Planner panel below to confirm.';
        session.messages.push({
          role: 'assistant',
          content: reply,
          results: [{ tool: 'organize_directory', success: true, blocked: false, output: 'Paused at awaiting_permission gate before moving or deleting files.' }]
        });
        updateEngineStatusUI();
        speakTextIfEnabled(reply, function () {
          if (continuousCallActive && !isListeningNow) startRealVoiceRecognition();
        });
        renderChatMessages();
        saveAppState();
        return;
      }

      setAgentStatus('thinking', 'Thinking...');
      const sysPrompt = (appState.personaSettings && appState.personaSettings.prompt) || 'You are Bajrang AI Pro.';
      const liveRes = await callLiveCloudAi(promptText, sysPrompt);
      if (liveRes.ok) {
        session.messages.push({
          role: 'assistant',
          content: liveRes.text,
          results: [{ tool: 'private_vault_api (' + liveRes.model + ')', success: true, blocked: false, output: 'Verified live response' }]
        });
        updateEngineStatusUI();
        renderChatMessages();
        saveAppState();
        speakTextIfEnabled(liveRes.text, function () {
          if (continuousCallActive && !isListeningNow) startRealVoiceRecognition();
        });
        return;
      }

      updateEngineStatusUI();
      const fallbackReply = (currentPrivateByo && currentPrivateByo.apiKey)
        ? ('API Error: ' + liveRes.error + '. Check your pasted API key in the top bar.')
        : ('I heard: "' + promptText + '". Paste your private Gemini (AIza*), Groq (gsk_*), or OpenAI (sk-*) API key in the top bar for live AI answers on mobile and web!');
      session.messages.push({ role: 'assistant', content: fallbackReply, results: [] });
      renderChatMessages();
      saveAppState();
      speakTextIfEnabled(fallbackReply, function () {
        if (continuousCallActive && !isListeningNow) startRealVoiceRecognition();
      });
    }

    function getActiveSession() {
      for (let i = 0; i < appState.sessions.length; i++) {
        if (appState.sessions[i].session_id === appState.currentSessionId) return appState.sessions[i];
      }
      return appState.sessions[0];
    }

    function createNewSession() {
      const newId = 'sess_' + Date.now();
      appState.sessions.unshift({
        session_id: newId,
        title: 'New Conversation',
        model: appState.selectedModel,
        updated_at: 'Just now',
        messages: [{ role: 'assistant', content: 'Started new session. Tap Speak Now or type below.', results: [] }]
      });
      appState.currentSessionId = newId;
      renderSessionList();
      renderChatMessages();
      saveAppState();
    }

    function selectSession(sessionId) {
      appState.currentSessionId = sessionId;
      renderSessionList();
      renderChatMessages();
      saveAppState();
    }

    function renderSessionList() {
      const listEl = document.getElementById('session-list');
      const countEl = document.getElementById('session-count-badge');
      const searchEl = document.getElementById('history-search-input');
      if (!listEl) return;
      const query = (searchEl ? searchEl.value : '').trim().toLowerCase();
      const filtered = appState.sessions.filter(function (s) {
        if (!query) return true;
        if (s.title.toLowerCase().indexOf(query) !== -1) return true;
        return s.messages.some(function (m) { return m.content.toLowerCase().indexOf(query) !== -1; });
      });
      if (countEl) countEl.textContent = String(filtered.length);
      listEl.innerHTML = '';
      filtered.forEach(function (sess) {
        const isCurrent = sess.session_id === appState.currentSessionId;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'w-full text-left px-2.5 py-2 rounded-xl text-xs transition flex items-center justify-between gap-1 ' +
          (isCurrent ? 'bg-indigo-600 text-white font-bold' : 'hover:bg-indigo-500/10 text-sec');
        btn.onclick = function () { selectSession(sess.session_id); };
        btn.innerHTML = '<span class="truncate">💬 ' + sess.title + '</span><span class="text-[10px] font-mono opacity-80">' + sess.messages.length + '</span>';
        listEl.appendChild(btn);
      });
    }

    function renderChatMessages() {
      const box = document.getElementById('chat-messages');
      if (!box) return;
      const session = getActiveSession();
      box.innerHTML = '';
      if (!session) return;
      session.messages.forEach(function (msg) {
        const wrap = document.createElement('div');
        if (msg.role === 'user') {
          wrap.className = 'bg-indigo-600/20 border border-indigo-500/40 rounded-2xl px-3.5 py-2.5 ml-6 font-medium';
          wrap.textContent = 'You: ' + msg.content;
        } else {
          wrap.className = 'theme-card rounded-2xl px-3.5 py-2.5 mr-4 space-y-2';
          const textP = document.createElement('div');
          textP.textContent = msg.content;
          wrap.appendChild(textP);
          if (Array.isArray(msg.results)) {
            msg.results.forEach(function (res) {
              const badge = document.createElement('div');
              const isErr = res.blocked || !res.success;
              badge.className = 'font-mono text-[11px] px-3 py-1.5 rounded-xl border ' +
                (isErr ? 'bg-red-500/15 border-red-500/40 text-red-500 font-semibold' : 'bg-emerald-500/15 border-emerald-500/35 text-emerald-500 font-semibold');
              badge.textContent = '[' + (res.blocked ? '🛑 BLOCKED' : '✅ VERIFIED') + ' • ' + res.tool + '] ' + res.output;
              wrap.appendChild(badge);
            });
          }
        }
        box.appendChild(wrap);
      });
      box.scrollTop = box.scrollHeight;
    }

