    function triggerBrowserDownload(filename, content, mimeType) {
      const blob = new Blob([content], { type: mimeType || 'text/plain;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      setTimeout(function () { URL.revokeObjectURL(url); a.remove(); }, 250);
      showToast('Downloaded ' + filename + '!');
    }

    async function decodeGzipBase64UrlBytes(b64urlStr) {
      const b64 = b64urlStr.replace(/-/g, '+').replace(/_/g, '/');
      const padLen = (4 - (b64.length % 4)) % 4;
      const padded = b64 + '='.repeat(padLen);
      const binStr = atob(padded);
      const bytes = new Uint8Array(binStr.length);
      for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
      if (typeof DecompressionStream !== 'undefined') {
        const ds = new DecompressionStream('gzip');
        const writer = ds.writable.getWriter();
        writer.write(bytes);
        writer.close();
        const resp = new Response(ds.readable);
        return new Uint8Array(await resp.arrayBuffer());
      }
      return bytes;
    }

    async function downloadPackageFile(filename) {
      const encoded = PACKAGED_GZ_B64URL[filename];
      if (!encoded) { showToast('File not found: ' + filename, 'error'); return; }
      try {
        const rawBytes = await decodeGzipBase64UrlBytes(encoded);
        const mime = filename.endsWith('.exe') ? 'application/octet-stream' : 'text/plain;charset=utf-8';
        appendSiemLog('INFO', 'PACKAGE_DOWNLOADED', null, 'Downloaded ' + filename);
        triggerBrowserDownload(filename, rawBytes, mime);
      } catch (err) {
        showToast('Download error for ' + filename, 'error');
      }
    }

    const CRC32_TABLE = (function () {
      const tbl = new Uint32Array(256);
      for (let i = 0; i < 256; i++) {
        let c = i;
        for (let k = 0; k < 8; k++) {
          c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
        }
        tbl[i] = c >>> 0;
      }
      return tbl;
    })();

    function computeCrc32(bytes) {
      let crc = 0xFFFFFFFF;
      for (let i = 0; i < bytes.length; i++) {
        crc = CRC32_TABLE[(crc ^ bytes[i]) & 0xFF] ^ (crc >>> 8);
      }
      return (crc ^ 0xFFFFFFFF) >>> 0;
    }

    function buildPkZipArchiveBytes(fileEntries) {
      const encoder = new TextEncoder();
      const localParts = [];
      const centralParts = [];
      let offset = 0;

      for (let i = 0; i < fileEntries.length; i++) {
        const nameBytes = encoder.encode(fileEntries[i].name);
        const dataBytes = fileEntries[i].bytes;
        const crc = computeCrc32(dataBytes);
        const size = dataBytes.length;

        const localHdr = new Uint8Array(30 + nameBytes.length);
        const lv = new DataView(localHdr.buffer);
        lv.setUint32(0, 0x04034b50, true);
        lv.setUint16(4, 20, true);
        lv.setUint16(6, 0, true);
        lv.setUint16(8, 0, true);
        lv.setUint16(10, 0, true);
        lv.setUint16(12, 0x566C, true);
        lv.setUint32(14, crc, true);
        lv.setUint32(18, size, true);
        lv.setUint32(22, size, true);
        lv.setUint16(26, nameBytes.length, true);
        lv.setUint16(28, 0, true);
        localHdr.set(nameBytes, 30);

        localParts.push(localHdr);
        localParts.push(dataBytes);

        const centralHdr = new Uint8Array(46 + nameBytes.length);
        const cv = new DataView(centralHdr.buffer);
        cv.setUint32(0, 0x02014b50, true);
        cv.setUint16(4, 20, true);
        cv.setUint16(6, 20, true);
        cv.setUint16(8, 0, true);
        cv.setUint16(10, 0, true);
        cv.setUint16(12, 0, true);
        cv.setUint16(14, 0x566C, true);
        cv.setUint32(16, crc, true);
        cv.setUint32(20, size, true);
        cv.setUint32(24, size, true);
        cv.setUint16(28, nameBytes.length, true);
        cv.setUint16(30, 0, true);
        cv.setUint16(32, 0, true);
        cv.setUint16(34, 0, true);
        cv.setUint16(36, 0, true);
        cv.setUint32(38, 0, true);
        cv.setUint32(42, offset, true);
        centralHdr.set(nameBytes, 46);
        centralParts.push(centralHdr);

        offset += localHdr.length + size;
      }

      let centralSize = 0;
      for (let i = 0; i < centralParts.length; i++) centralSize += centralParts[i].length;

      const eocd = new Uint8Array(22);
      const ev = new DataView(eocd.buffer);
      ev.setUint32(0, 0x06054b50, true);
      ev.setUint16(4, 0, true);
      ev.setUint16(6, 0, true);
      ev.setUint16(8, fileEntries.length, true);
      ev.setUint16(10, fileEntries.length, true);
      ev.setUint32(12, centralSize, true);
      ev.setUint32(16, offset, true);
      ev.setUint16(20, 0, true);

      const totalLen = offset + centralSize + 22;
      const out = new Uint8Array(totalLen);
      let pos = 0;
      for (let i = 0; i < localParts.length; i++) {
        out.set(localParts[i], pos);
        pos += localParts[i].length;
      }
      for (let i = 0; i < centralParts.length; i++) {
        out.set(centralParts[i], pos);
        pos += centralParts[i].length;
      }
      out.set(eocd, pos);
      return out;
    }

    async function downloadBundleAsZip(bundleType) {
      let fileList = [];
      let zipFilename = 'BajrangAI_All_Platforms_Complete_Bundle.zip';

      if (bundleType === 'windows') {
        zipFilename = 'BajrangAI_Windows11_Complete_Bundle.zip';
        fileList = [
          'README_INSTRUCTIONS.txt',
          'README.md',
          'SECURITY.md',
          'BajrangAI_Pro_Setup.exe',
          'bajrang_core.py',
          'windows.py',
          'bajrang_windows.py',
          'installer_windows.py',
          'setup_windows.bat',
          'requirements-common.txt',
          'requirements-windows.txt',
          'requirements_windows.txt'
        ];
      } else if (bundleType === 'fedora') {
        zipFilename = 'BajrangAI_Fedora_Linux_Complete_Bundle.zip';
        fileList = [
          'README_INSTRUCTIONS.txt',
          'README.md',
          'SECURITY.md',
          'bajrang_core.py',
          'fedora.py',
          'bajrang_llama32.py',
          'setup_fedora.sh',
          'requirements-common.txt',
          'requirements-fedora.txt',
          'requirements_fedora.txt'
        ];
      } else {
        zipFilename = 'BajrangAI_All_Platforms_Complete_Bundle.zip';
        fileList = [
          'README_INSTRUCTIONS.txt',
          'README.md',
          'SECURITY.md',
          'BajrangAI_Pro_Setup.exe',
          'bajrang_core.py',
          'windows.py',
          'bajrang_windows.py',
          'fedora.py',
          'bajrang_llama32.py',
          'installer_windows.py',
          'setup_windows.bat',
          'setup_fedora.sh',
          'requirements-common.txt',
          'requirements-windows.txt',
          'requirements-fedora.txt',
          'requirements_windows.txt',
          'requirements_fedora.txt'
        ];
      }

      showToast('Building single-file archive ' + zipFilename + '...');
      const entries = [];
      for (let i = 0; i < fileList.length; i++) {
        const fname = fileList[i];
        const enc = PACKAGED_GZ_B64URL[fname];
        if (enc) {
          const decodedBytes = await decodeGzipBase64UrlBytes(enc);
          entries.push({ name: fname, bytes: decodedBytes });
        }
      }
      updateModelfilePreview();
      const pre = document.getElementById('modelfile-preview-box');
      const mfText = pre ? pre.textContent : 'FROM llama3.2';
      entries.push({ name: 'Modelfile.bajrang', bytes: new TextEncoder().encode(mfText) });

      const zipBytes = buildPkZipArchiveBytes(entries);
      appendSiemLog('INFO', 'ZIP_BUNDLE_DOWNLOADED', null, 'Downloaded ' + zipFilename + ' (' + entries.length + ' files)');
      triggerBrowserDownload(zipFilename, zipBytes, 'application/zip');
    }

